// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count all Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th starting from 0001-01-01 ---
DateOnly search = new(1, 1, 13); // start checking the 13th of each month
DateOnly earliest = default;

while (search.Year <= 400)
{
    if (search.DayOfWeek == DayOfWeek.Friday)
    {
        earliest = search;
        break;
    }
    search = search.AddMonths(1);
}

Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");

// --- Count in a full 400-year cycle (0001-01-01 to 0400-12-31) ---
int count = 0;
DateOnly d = new(1, 1, 13);

while (d.Year <= 400)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
    d = d.AddMonths(1);
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");

// --- Bonus: distribution by month ---
int[] byMonth = new int[13];
d = new(1, 1, 13);
while (d.Year <= 400)
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        byMonth[d.Month]++;
    d = d.AddMonths(1);
}

Console.WriteLine("\nDistribution by month:");
for (int m = 1; m <= 12; m++)
    Console.WriteLine($"  {new DateOnly(2000, m, 1):MMMM,-12} {byMonth[m]}");

